#!/usr/bin/env python3
import base64, os
BASE = "/workspaces/Sonalit/frontend/src"
files = {}
data = {'CommandBar.jsx': '', 'WarRoom.jsx': '', 'OfflineBanner.jsx': '', 'FleetPage.jsx': '', 'ConvoysPage.jsx': '', 'AlertsPage.jsx': '', 'offline.js': '', 'sw.js': '', 'App.jsx': '', 'api.js': ''}

destinations = {
    "CommandBar.jsx": BASE+"/components/CommandBar.jsx",
    "WarRoom.jsx": BASE+"/components/WarRoom.jsx",
    "OfflineBanner.jsx": BASE+"/components/OfflineBanner.jsx",
    "FleetPage.jsx": BASE+"/pages/FleetPage.jsx",
    "ConvoysPage.jsx": BASE+"/pages/ConvoysPage.jsx",
    "AlertsPage.jsx": BASE+"/pages/AlertsPage.jsx",
    "offline.js": BASE+"/services/offline.js",
    "sw.js": "/workspaces/Sonalit/frontend/public/sw.js",
    "App.jsx": BASE+"/App.jsx",
    "api.js": BASE+"/services/api.js",
}
for name, dst in destinations.items():
    os.makedirs(os.path.dirname(dst), exist_ok=True)
    open(dst,"wb").write(base64.b64decode(data[name]))
    print(f"✅ {name} -> {dst}")
print("\n🚀 All components deployed!")
